/**
 * tools/svgRaster.js
 * Dev-only minimal SVG rasteriser (paths/arcs/rects/circles/text-skip) used to
 * eyeball the procedural ticket art outside a browser. Supports the subset
 * generated by src/visuals/tickets.js: M L H V C Q A Z, transforms, fills,
 * strokes (approximated by outline dilation) and group opacity.
 */

import fs from "node:fs";
import zlib from "node:zlib";

const TAU = Math.PI * 2;

// --------------------------------------------------------------------------
// Path parsing
// --------------------------------------------------------------------------

function tokens(d) {
  return d.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/gi) || [];
}

function arcToPoints(x0, y0, rx, ry, rotDeg, largeArc, sweep, x1, y1, steps = 18) {
  if (rx === 0 || ry === 0) return [[x1, y1]];
  const phi = (rotDeg * Math.PI) / 180;
  const cosPhi = Math.cos(phi);
  const sinPhi = Math.sin(phi);
  const dx2 = (x0 - x1) / 2;
  const dy2 = (y0 - y1) / 2;
  const x1p = cosPhi * dx2 + sinPhi * dy2;
  const y1p = -sinPhi * dx2 + cosPhi * dy2;
  rx = Math.abs(rx);
  ry = Math.abs(ry);
  const lambda = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry);
  if (lambda > 1) {
    rx *= Math.sqrt(lambda);
    ry *= Math.sqrt(lambda);
  }
  const sign = largeArc === sweep ? -1 : 1;
  const num = rx * rx * ry * ry - rx * rx * y1p * y1p - ry * ry * x1p * x1p;
  const den = rx * rx * y1p * y1p + ry * ry * x1p * x1p;
  const coef = sign * Math.sqrt(Math.max(0, num / den));
  const cxp = (coef * rx * y1p) / ry;
  const cyp = (-coef * ry * x1p) / rx;
  const cx = cosPhi * cxp - sinPhi * cyp + (x0 + x1) / 2;
  const cy = sinPhi * cxp + cosPhi * cyp + (y0 + y1) / 2;
  const angle = (ux, uy, vx, vy) => {
    const dotv = ux * vx + uy * vy;
    const len = Math.hypot(ux, uy) * Math.hypot(vx, vy) || 1;
    const a = Math.acos(Math.max(-1, Math.min(1, dotv / len)));
    return ux * vy - uy * vx < 0 ? -a : a;
  };
  const theta1 = angle(1, 0, (x1p - cxp) / rx, (y1p - cyp) / ry);
  let dtheta = angle((x1p - cxp) / rx, (y1p - cyp) / ry, (-x1p - cxp) / rx, (-y1p - cyp) / ry);
  if (!sweep && dtheta > 0) dtheta -= TAU;
  if (sweep && dtheta < 0) dtheta += TAU;
  const pts = [];
  for (let i = 1; i <= steps; i += 1) {
    const th = theta1 + (dtheta * i) / steps;
    const ex = cx + rx * Math.cos(th) * cosPhi - ry * Math.sin(th) * sinPhi;
    const ey = cy + rx * Math.cos(th) * sinPhi + ry * Math.sin(th) * cosPhi;
    pts.push([ex, ey]);
  }
  return pts;
}

/** Returns an array of subpaths: [[x,y], ...]. */
export function parsePath(d) {
  const t = tokens(d);
  const subs = [];
  let cur = [];
  let x = 0;
  let y = 0;
  let startX = 0;
  let startY = 0;
  let cmd = null;
  let i = 0;
  const num = () => parseFloat(t[i++]);

  const flush = () => {
    if (cur.length > 1) subs.push(cur);
    cur = [];
  };

  while (i < t.length) {
    if (/[a-zA-Z]/.test(t[i])) cmd = t[i++];
    const rel = cmd === cmd.toLowerCase();
    const C = cmd.toUpperCase();
    if (C === "M") {
      const nx = num();
      const ny = num();
      x = rel ? x + nx : nx;
      y = rel ? y + ny : ny;
      flush();
      cur = [[x, y]];
      startX = x;
      startY = y;
      cmd = rel ? "l" : "L";
    } else if (C === "L") {
      const nx = num();
      const ny = num();
      x = rel ? x + nx : nx;
      y = rel ? y + ny : ny;
      cur.push([x, y]);
    } else if (C === "H") {
      const nx = num();
      x = rel ? x + nx : nx;
      cur.push([x, y]);
    } else if (C === "V") {
      const ny = num();
      y = rel ? y + ny : ny;
      cur.push([x, y]);
    } else if (C === "C") {
      const x1 = num();
      const y1 = num();
      const x2 = num();
      const y2 = num();
      const x3 = num();
      const y3 = num();
      const c1 = rel ? [x + x1, y + y1] : [x1, y1];
      const c2 = rel ? [x + x2, y + y2] : [x2, y2];
      const p3 = rel ? [x + x3, y + y3] : [x3, y3];
      for (let s = 1; s <= 10; s += 1) {
        const u = s / 10;
        const mu = 1 - u;
        cur.push([
          mu ** 3 * x + 3 * mu * mu * u * c1[0] + 3 * mu * u * u * c2[0] + u ** 3 * p3[0],
          mu ** 3 * y + 3 * mu * mu * u * c1[1] + 3 * mu * u * u * c2[1] + u ** 3 * p3[1],
        ]);
      }
      [x, y] = p3;
    } else if (C === "Q") {
      const x1 = num();
      const y1 = num();
      const x2 = num();
      const y2 = num();
      const c1 = rel ? [x + x1, y + y1] : [x1, y1];
      const p2 = rel ? [x + x2, y + y2] : [x2, y2];
      for (let s = 1; s <= 8; s += 1) {
        const u = s / 8;
        const mu = 1 - u;
        cur.push([mu * mu * x + 2 * mu * u * c1[0] + u * u * p2[0], mu * mu * y + 2 * mu * u * c1[1] + u * u * p2[1]]);
      }
      [x, y] = p2;
    } else if (C === "A") {
      const rx = num();
      const ry = num();
      const rot = num();
      const large = num();
      const sweep = num();
      const nx = num();
      const ny = num();
      const ex = rel ? x + nx : nx;
      const ey = rel ? y + ny : ny;
      cur.push(...arcToPoints(x, y, rx, ry, rot, large, sweep, ex, ey));
      x = ex;
      y = ey;
    } else if (C === "Z") {
      cur.push([startX, startY]);
      flush();
      x = startX;
      y = startY;
    } else {
      i += 1;
    }
  }
  flush();
  return subs;
}

// --------------------------------------------------------------------------
// Raster
// --------------------------------------------------------------------------

class Surface {
  constructor(w, h) {
    this.w = w;
    this.h = h;
    this.data = new Uint8ClampedArray(w * h * 4);
  }
  blend(x, y, [r, g, b, a]) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h || a <= 0) return;
    const i = (y * this.w + x) * 4;
    const d = this.data;
    d[i] = d[i] * (1 - a) + r * a;
    d[i + 1] = d[i + 1] * (1 - a) + g * a;
    d[i + 2] = d[i + 2] * (1 - a) + b * a;
    d[i + 3] = Math.min(255, d[i + 3] + a * 255);
  }
  fillPolys(subs, color, alpha) {
    if (!subs.length) return;
    let minY = Infinity;
    let maxY = -Infinity;
    for (const s of subs) for (const [, y] of s) { if (y < minY) minY = y; if (y > maxY) maxY = y; }
    const y0 = Math.max(0, Math.floor(minY));
    const y1 = Math.min(this.h - 1, Math.ceil(maxY));
    for (let py = y0; py <= y1; py += 1) {
      const cy = py + 0.5;
      const xs = [];
      for (const s of subs) {
        for (let i = 0; i < s.length; i += 1) {
          const a = s[i];
          const b = s[(i + 1) % s.length];
          if ((a[1] <= cy && b[1] > cy) || (b[1] <= cy && a[1] > cy)) {
            xs.push(a[0] + ((cy - a[1]) / (b[1] - a[1])) * (b[0] - a[0]));
          }
        }
      }
      xs.sort((p, q) => p - q);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        const sx = Math.max(0, Math.round(xs[k]));
        const ex = Math.min(this.w - 1, Math.round(xs[k + 1]) - 1);
        for (let px = sx; px <= ex; px += 1) this.blend(px, py, [...color, alpha]);
      }
    }
  }
  fillCircle(cx, cy, r, color, alpha) {
    for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y += 1) {
      for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x += 1) {
        if ((x + 0.5 - cx) ** 2 + (y + 0.5 - cy) ** 2 <= r * r) this.blend(x, y, [...color, alpha]);
      }
    }
  }
  strokeCircle(cx, cy, r, w, color, alpha) {
    for (let y = Math.floor(cy - r - w); y <= Math.ceil(cy + r + w); y += 1) {
      for (let x = Math.floor(cx - r - w); x <= Math.ceil(cx + r + w); x += 1) {
        const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
        if (d <= r + w / 2 && d >= r - w / 2) this.blend(x, y, [...color, alpha]);
      }
    }
  }
  fillEllipse(cx, cy, rx, ry, color, alpha) {
    for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y += 1) {
      for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x += 1) {
        if (((x + 0.5 - cx) / rx) ** 2 + ((y + 0.5 - cy) / ry) ** 2 <= 1) this.blend(x, y, [...color, alpha]);
      }
    }
  }
  strokePolys(subs, w, color, alpha) {
    for (const s of subs) {
      for (let i = 1; i < s.length; i += 1) {
        const [x0, y0] = s[i - 1];
        const [x1, y1] = s[i];
        const steps = Math.ceil(Math.hypot(x1 - x0, y1 - y0) * 2) + 1;
        for (let k = 0; k <= steps; k += 1) {
          const t = k / steps;
          const px = x0 + (x1 - x0) * t;
          const py = y0 + (y1 - y0) * t;
          this.fillCircle(px, py, w / 2, color, alpha);
        }
      }
    }
  }
}

export function parseColor(str) {
  if (!str || str === "none") return null;
  const s = String(str).trim();
  if (s.startsWith("#")) {
    const v = s.length === 4
      ? [parseInt(s[1] + s[1], 16), parseInt(s[2] + s[2], 16), parseInt(s[3] + s[3], 16)]
      : [parseInt(s.slice(1, 3), 16), parseInt(s.slice(3, 5), 16), parseInt(s.slice(5, 7), 16)];
    return v;
  }
  const m = s.match(/rgba?\(([^)]+)\)/);
  if (m) {
    const p = m[1].split(",").map((q) => parseFloat(q));
    return [p[0], p[1], p[2]];
  }
  return [0, 0, 0];
}

function applyTransform(pt, tf) {
  let [x, y] = pt;
  if (tf.scale !== 1) {
    x *= tf.scale;
    y *= tf.scale;
  }
  if (tf.rotate) {
    const c = Math.cos(tf.rotate);
    const s = Math.sin(tf.rotate);
    const ox = tf.rotateOrigin ? tf.rotateOrigin[0] : 0;
    const oy = tf.rotateOrigin ? tf.rotateOrigin[1] : 0;
    const dx = x - ox;
    const dy = y - oy;
    x = ox + dx * c - dy * s;
    y = oy + dx * s + dy * c;
  }
  return [x + tf.tx, y + tf.ty];
}

function attrMap(tag) {
  const map = {};
  for (const m of tag.matchAll(/([a-zA-Z-]+)="([^"]*)"/g)) map[m[1]] = m[2];
  return map;
}

function transformFrom(str, base) {
  const tf = { ...base };
  if (!str) return tf;
  const t = str.trim();
  let m = t.match(/translate\(\s*(-?[\d.]+)[ ,]+(-?[\d.]+)?\s*\)/);
  if (m) {
    tf.tx += parseFloat(m[1]) * base.scale;
    tf.ty += parseFloat(m[2] || 0) * base.scale;
  }
  m = t.match(/scale\(\s*(-?[\d.]+)\s*\)/);
  if (m) tf.scale *= parseFloat(m[1]);
  m = t.match(/rotate\(\s*(-?[\d.]+)\s*(?:[ ,]\s*(-?[\d.]+)[ ,]+(-?[\d.]+))?\)/);
  if (m) {
    tf.rotate = (tf.rotate || 0) + (parseFloat(m[1]) * Math.PI) / 180;
    if (m[2] !== undefined) tf.rotateOrigin = [parseFloat(m[2]), parseFloat(m[3])];
  }
  return tf;
}

/** Rasterise an SVG string to a Surface at `scale`x. */
export function rasterizeSvg(svg, scale = 4) {
  const viewBox = (svg.match(/viewBox="([^"]+)"/) || [])[1] || "0 0 100 140";
  const [, , vbW, vbH] = viewBox.split(/\s+/).map(Number);
  const surf = new Surface(Math.round(vbW * scale), Math.round(vbH * scale));
  // White background so opacity reads like paper.
  for (let i = 0; i < surf.data.length; i += 4) {
    surf.data[i] = 255;
    surf.data[i + 1] = 255;
    surf.data[i + 2] = 255;
    surf.data[i + 3] = 255;
  }
  walk(svg, surf, { tx: 0, ty: 0, scale, rotate: 0 }, 1);
  return surf;
}

function walk(svg, surf, tf0, alpha0) {
  const re = /<\/?([a-zA-Z]+)((?:"[^"]*"|[^>"])*)>/g;
  let m;
  const stack = [];
  while ((m = re.exec(svg))) {
    const closing = m[0].startsWith("</");
    const tag = m[1].toLowerCase();
    if (closing) {
      if (tag === "g" || tag === "svg" || tag === "defs" || tag === "clippath") stack.pop();
      continue;
    }
    const a = attrMap(m[2]);
    const selfClosing = m[0].endsWith("/>");
    const tf = transformFrom(a.transform, stack.length ? stack[stack.length - 1].tf : tf0);
    const alpha = (stack.length ? stack[stack.length - 1].alpha : alpha0) * (a.opacity ? parseFloat(a.opacity) : 1);
    if (tag === "g" || tag === "svg" || tag === "defs" || tag === "clippath") {
      if (!selfClosing) stack.push({ tf, alpha });
      continue;
    }
    if (tag === "text") continue; // no font metrics in Node
    const fill = parseColor(a.fill);
    const stroke = parseColor(a.stroke);
    const sw = a["stroke-width"] ? parseFloat(a["stroke-width"]) : 1;
    const scale = tf.scale;
    const toScreen = (pt) => applyTransform(pt, tf);

    const paint = (subs) => {
      const scaled = subs.map((s) => s.map(toScreen));
      if (fill) surf.fillPolys(scaled, fill, alpha);
      if (stroke) surf.strokePolys(scaled, Math.max(1, sw * scale), stroke, alpha);
    };

    if (tag === "rect") {
      const x = parseFloat(a.x || 0);
      const y = parseFloat(a.y || 0);
      const w = parseFloat(a.width || 0);
      const h = parseFloat(a.height || 0);
      const subs = [[[x, y], [x + w, y], [x + w, y + h], [x, y + h]]];
      const scaled = subs.map((s) => s.map(toScreen));
      if (fill) surf.fillPolys(scaled, fill, alpha);
      if (stroke) surf.strokePolys(scaled, Math.max(1, sw * scale), stroke, alpha);
    } else if (tag === "circle") {
      const cx = parseFloat(a.cx || 0);
      const cy = parseFloat(a.cy || 0);
      const r = parseFloat(a.r || 0);
      const [sx, sy] = toScreen([cx, cy]);
      if (fill) surf.fillCircle(sx, sy, r * scale, fill, alpha);
      if (stroke) surf.strokeCircle(sx, sy, r * scale, Math.max(1, sw * scale), stroke, alpha);
    } else if (tag === "ellipse") {
      const cx = parseFloat(a.cx || 0);
      const cy = parseFloat(a.cy || 0);
      const rx = parseFloat(a.rx || 0);
      const ry = parseFloat(a.ry || 0);
      const [sx, sy] = toScreen([cx, cy]);
      surf.fillEllipse(sx, sy, rx * scale, ry * scale, fill || [0, 0, 0], alpha);
    } else if (tag === "path") {
      paint(parsePath(a.d || ""));
    }
  }
}

// --------------------------------------------------------------------------
// PNG out (reuse palette-free writer)
// --------------------------------------------------------------------------

function crc32(buf) {
  let c;
  const table = crc32.table || (crc32.table = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n += 1) {
      c = n;
      for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c >>> 0;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i += 1) crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const t = Buffer.from(type, "ascii");
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([t, data])), 0);
  return Buffer.concat([len, t, data, crc]);
}

export function writePng(file, surf) {
  const { w, h, data } = surf;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  let o = 0;
  for (let y = 0; y < h; y += 1) {
    raw[o] = 0;
    o += 1;
    for (let x = 0; x < w; x += 1) {
      const i = (y * w + x) * 4;
      raw[o] = data[i];
      raw[o + 1] = data[i + 1];
      raw[o + 2] = data[i + 2];
      raw[o + 3] = 255;
      o += 4;
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  const png = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
  fs.writeFileSync(file, png);
}

/** Compose several surfaces into a contact sheet. */
export function contactSheet(surfaces, columns, gap = 8) {
  const w = surfaces[0].w;
  const h = surfaces[0].h;
  const rows = Math.ceil(surfaces.length / columns);
  const sheet = new Surface(columns * w + (columns + 1) * gap, rows * h + (rows + 1) * gap);
  for (let i = 0; i < sheet.data.length; i += 4) {
    sheet.data[i] = 12;
    sheet.data[i + 1] = 16;
    sheet.data[i + 2] = 24;
    sheet.data[i + 3] = 255;
  }
  surfaces.forEach((s, i) => {
    const cx = gap + (i % columns) * (w + gap);
    const cy = gap + Math.floor(i / columns) * (h + gap);
    for (let y = 0; y < s.h; y += 1) {
      for (let x = 0; x < s.w; x += 1) {
        const si = (y * s.w + x) * 4;
        const di = ((cy + y) * sheet.w + (cx + x)) * 4;
        sheet.data[di] = s.data[si];
        sheet.data[di + 1] = s.data[si + 1];
        sheet.data[di + 2] = s.data[si + 2];
      }
    }
  });
  return sheet;
}
